// Generated by the sprint-16..19 frontend split (see docs/refactor_2026-09/sprints.md).
// Ported near-verbatim from harmonia_min/app_shell.html's single <script> — see that
// file's own top-of-script comment for the app's history. Behaviour is unchanged;
// only the module boundary is new.


import { api } from "../api.js";
import { appBar, screenWrap } from "../router.js";
import { micErrorMessage, requestMic } from "../screens/analyse.js";
import { T, UI, el, toast } from "../ui/kit.js";

// The single DOM host div (`<div id="app">`) — there is exactly one call
// site, `window.APP.build(document.getElementById("app"))` in main.js, so
// every module that touches the screen host just looks it up itself rather
// than threading a mutable binding through every import (see sprint 16-19
// report: root/S design choice).
const root = document.getElementById("app");

  // ── Jam Mode (2026-07-20, experimental): live loop listener ──────────────
  // Near-live, not live-live, by explicit design — accuracy over latency.
  // Records in ~8s chunks, uploads each to the server which redecodes the
  // WHOLE session buffer and returns the current best-fit loop + confidence;
  // this screen just renders whatever state came back from the last chunk.
export function renderJam(){
    const w=screenWrap();
    w.appendChild(appBar(null,"Jam","library"));
    const body=el("div","flex:1;overflow-y:auto;padding:20px;"); body.className="ap-scroll";
    const inner=el("div","max-width:520px;margin:0 auto;display:flex;flex-direction:column;gap:16px;");

    const hint=el("div",`font:500 13px ${UI};color:${T.faint};text-align:center;`,"Tape pour lancer. Joue la boucle deux ou trois fois — elle se verrouille, et elle se nettoie à chaque tour.");
    const status=el("div",`font:600 13px ${UI};color:${T.faint};text-align:center;`,"");
    const loopStrip=el("div","display:flex;flex-wrap:wrap;gap:8px;justify-content:center;min-height:52px;");
    const partsBox=el("div","display:flex;flex-direction:column;gap:8px;");
    const btn=el("button",`align-self:center;width:96px;height:96px;border-radius:50%;border:none;background:${T.accent};color:#fff;font:700 14px ${UI};cursor:pointer;box-shadow:0 10px 26px -12px rgba(190,90,40,.55);`,"START");

    inner.appendChild(hint); inner.appendChild(btn); inner.appendChild(status);
    inner.appendChild(loopStrip); inner.appendChild(partsBox);
    body.appendChild(inner); w.appendChild(body);

    const chip=(c)=>{
      const b=el("div",`padding:10px 14px;border-radius:10px;font:700 15px ${UI};background:${T.card};border:1.5px solid ${c.confidence>0.7?T.accent:T.line};color:${T.ink};opacity:${0.45+0.55*c.confidence};`, c.label==="N"?"N.C.":c.label);
      return b;
    };
    const renderState=(st)=>{
      loopStrip.innerHTML=""; partsBox.innerHTML="";
      // « en écoute » n'est pas décoratif : une passe redécode TOUT le tampon
      // (~13 s sur 80 s de jam) pendant que les morceaux continuent d'arriver
      // toutes les 8 s. Sans ce mot, l'écran a l'air figé alors qu'il travaille.
      status.textContent=`${(st.elapsed_s/60|0)}:${String(Math.round(st.elapsed_s%60)).padStart(2,"0")} enregistré`
        +(st.decoding?" · en écoute…":"");
      if(st.current){
        // `stale` = la dernière passe n'a pas su retrouver la boucle. On garde
        // les accords en retrait plutôt que de vider l'écran (voir
        // JamSession._abstain côté serveur) : sur un vrai vamp la détection
        // décroche une passe sur trois alors que le jam n'a pas bougé.
        loopStrip.style.opacity=st.current.stale?"0.45":"1";
        st.current.loop.forEach(c=>loopStrip.appendChild(chip(c)));
        const meta=el("div",`font:500 11px ${UI};color:${T.faint};text-align:center;width:100%;margin-top:2px;`,
          `boucle de ${st.current.period_beats} temps · ×${st.current.n_reps} tours · ${Math.round(st.current.tempo_bpm)} BPM`
          +(st.current.stale?" · à confirmer":""));
        loopStrip.appendChild(meta);
      } else {
        loopStrip.style.opacity="1";
        loopStrip.appendChild(el("div",`font:500 13px ${UI};color:${T.faint};`,
          st.elapsed_s<20?"joue la boucle deux ou trois fois…":"pas encore de boucle qui se répète…"));
      }
      st.parts.forEach((p,i)=>{
        const row=el("div",`display:flex;flex-wrap:wrap;gap:6px;align-items:center;padding:10px;border:1px solid ${T.line};border-radius:10px;`);
        row.appendChild(el("div",`font:700 11px ${UI};color:${T.faint};margin-right:4px;`,`Partie ${i+1} :`));
        p.loop.forEach(c=>row.appendChild(chip(c)));
        partsBox.appendChild(row);
      });
    };

    let stream=null, rec=null, sessionId=null, running=false, chunkTimer=null;
    const stopAll=()=>{
      running=false;
      if(chunkTimer) clearInterval(chunkTimer);
      if(rec && rec.state!=="inactive") rec.stop();
      if(stream) stream.getTracks().forEach(tr=>tr.stop());
      if(sessionId) api.post("/api/jam/stop",{session_id:sessionId}).catch(()=>{});
      btn.textContent="START"; btn.style.background=T.accent;
    };
    const uploadChunk=async(blob)=>{
      if(!sessionId || blob.size<500) return;
      try{
        const fd=new FormData();
        fd.append("audio", blob, "chunk.webm");
        fd.append("session_id", sessionId);
        const st=await fetch("/api/jam/chunk",{method:"POST",body:fd}).then(x=>x.json());
        if(st.error){ status.textContent=st.error; return; }
        renderState(st);
      }catch(e){ /* one dropped chunk shouldn't stop the jam */ }
    };
    btn.onclick=async()=>{
      if(running){ stopAll(); return; }
      try{ stream=await requestMic(); }
      catch(e){ toast(micErrorMessage(e)); return; }
      const r=await api.post("/api/jam/start",{});
      sessionId=r.session_id;
      running=true;
      btn.textContent="STOP"; btn.style.background=T.deep;
      // ~8s rolling chunks: MediaRecorder restarted each cycle rather than one
      // continuous timeslice stream — simpler to reason about (each blob is
      // a self-contained webm, no cross-chunk container continuity needed
      // server-side) at the cost of a small gap at each restart boundary.
      const cycle=()=>{
        if(!running) return;
        const chunks=[];
        rec=new MediaRecorder(stream);
        rec.ondataavailable=e=>{ if(e.data && e.data.size) chunks.push(e.data); };
        rec.onstop=()=>{ if(chunks.length) uploadChunk(new Blob(chunks,{type:rec.mimeType||"audio/webm"})); };
        rec.start();
        setTimeout(()=>{ if(rec && rec.state==="recording") rec.stop(); }, 8000);
      };
      cycle();
      chunkTimer=setInterval(cycle, 8200);
    };
    return w;
  }

